import {useRef} from 'react'
import {StyleSheet, TouchableWithoutFeedback, View} from 'react-native'
import Animated, {FadeIn, FadeOut} from 'react-native-reanimated'
import {RemoveScrollBar} from 'react-remove-scroll-bar'

import {usePalette} from '#/lib/hooks/usePalette'
import {useWebMediaQueries} from '#/lib/hooks/useWebMediaQueries'
import {type Modal as ModalIface} from '#/state/modals'
import {useModalControls, useModals} from '#/state/modals'
import {VideoEmbed} from '../util/post-embeds/VideoEmbed.web'
import * as CallInvitationModal from './CallInvitation'
import * as ChangePasswordModal from './ChangePassword'
import * as ConfirmModal from './ConfirmModal'
import * as CreateOrEditListModal from './CreateOrEditList'
import * as CropImageModal from './CropImage.web'
import * as DeleteAccountModal from './DeleteAccount'
import * as EditProfileModal from './EditProfile'
import * as InviteCodesModal from './InviteCodes'
import * as ContentLanguagesSettingsModal from './lang-settings/ContentLanguagesSettings'
import * as PostLanguagesSettingsModal from './lang-settings/PostLanguagesSettings'
import * as LinkWarningModal from './LinkWarning'
import * as StripePaymentConfirmationModal from './StripePaymentConfirmationModal'
import * as StripePaymentSuccessModal from './StripePaymentSuccessModal'
import * as UserAddRemoveLists from './UserAddRemoveLists'
import * as VerificationCompleteModal from './VerificationComplete'

export function ModalsContainer() {
  const {isModalActive, activeModals} = useModals()

  if (!isModalActive) {
    return null
  }

  return (
    <>
      <RemoveScrollBar />
      {activeModals.map((modal, i) => (
        <Modal key={`modal-${i}`} modal={modal} />
      ))}
    </>
  )
}

function Modal({modal}: {modal: ModalIface}) {
  const {isModalActive} = useModals()
  const {closeModal} = useModalControls()
  const pal = usePalette('default')
  const {isMobile} = useWebMediaQueries()
  const modalVideoRef = useRef<HTMLVideoElement | null>(null)

  if (!isModalActive) {
    return null
  }

  const onPressMask = () => {
    if (modal.name === 'crop-image') {
      return // dont close on mask presses during crop
    }
    if (modal.name === 'video-fullscreen' && modalVideoRef.current) {
      if (modal.videoRef?.current) {
        modal.videoRef.current.currentTime =
          modalVideoRef.current?.currentTime ?? 0
      }
      modalVideoRef.current?.pause()
      modalVideoRef.current = null // reset the ref to avoid memory leaks
    }
    closeModal()
  }
  const onInnerPress = () => {
    // TODO: can we use prevent default?
    // do nothing, we just want to stop it from bubbling
  }

  let element
  if (modal.name === 'edit-profile') {
    element = <EditProfileModal.Component {...modal} />
  } else if (modal.name === 'create-or-edit-list') {
    element = <CreateOrEditListModal.Component {...modal} />
  } else if (modal.name === 'user-add-remove-lists') {
    element = <UserAddRemoveLists.Component {...modal} />
  } else if (modal.name === 'crop-image') {
    element = <CropImageModal.Component {...modal} />
  } else if (modal.name === 'delete-account') {
    element = <DeleteAccountModal.Component />
  } else if (modal.name === 'invite-codes') {
    element = <InviteCodesModal.Component />
  } else if (modal.name === 'content-languages-settings') {
    element = <ContentLanguagesSettingsModal.Component />
  } else if (modal.name === 'post-languages-settings') {
    element = <PostLanguagesSettingsModal.Component />
  } else if (modal.name === 'change-password') {
    element = <ChangePasswordModal.Component />
  } else if (modal.name === 'link-warning') {
    element = <LinkWarningModal.Component {...modal} />
  } else if (modal.name === 'video-fullscreen') {
    element = (
      <VideoEmbed embed={modal.embed} hideFullScreen videoRef={modalVideoRef} />
    )
    setTimeout(() => {
      if (!modalVideoRef.current) return

      modalVideoRef.current.currentTime = modal.lastKnownTime ?? 0
      modal.videoRef?.current?.pause()
      modalVideoRef.current?.play().catch(() => {})
      modalVideoRef.current.muted = modal.videoRef?.current?.muted ?? false
    }, 100)
  } else if (modal.name === 'call') {
    element = <CallInvitationModal.Component {...modal} />
  } else if (modal.name === 'verification-complete') {
    element = <VerificationCompleteModal.Component {...modal} />
  } else if (modal.name === 'stripe-payment-confirmation') {
    element = <StripePaymentConfirmationModal.Component />
  } else if (modal.name === 'stripe-payment-success') {
    element = <StripePaymentSuccessModal.Component {...modal} />
  } else if (modal.name === 'confirm') {
    element = <ConfirmModal.Component {...modal} />
  } else {
    return null
  }

  return (
    // eslint-disable-next-line react-native-a11y/has-valid-accessibility-descriptors
    <TouchableWithoutFeedback onPress={onPressMask}>
      <Animated.View
        style={styles.mask}
        entering={FadeIn.duration(150)}
        exiting={FadeOut}>
        {/* eslint-disable-next-line react-native-a11y/has-valid-accessibility-descriptors */}
        <TouchableWithoutFeedback onPress={onInnerPress}>
          <View
            style={[
              styles.container,
              modal.name === 'video-fullscreen' && styles.widthScreen,
              [
                'verification-complete',
                'stripe-payment-confirmation',
                'stripe-payment-success',
              ].includes(modal.name) && styles.widthAuto,
              isMobile && styles.containerMobile,
              pal.view,
              pal.border,
            ]}>
            {element}
          </View>
        </TouchableWithoutFeedback>
      </Animated.View>
    </TouchableWithoutFeedback>
  )
}

const styles = StyleSheet.create({
  mask: {
    // @ts-ignore
    position: 'fixed',
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    backgroundColor: '#000c',
    alignItems: 'center',
    justifyContent: 'center',
  },
  container: {
    width: 600,
    // @ts-ignore web only
    maxWidth: '100vw',
    // @ts-ignore web only
    maxHeight: '90vh',
    paddingVertical: 20,
    paddingHorizontal: 24,
    borderRadius: 8,
    borderWidth: 1,
  },
  widthScreen: {
    // @ts-ignore web only
    width: '100vw',
  },
  containerMobile: {
    borderRadius: 0,
    paddingHorizontal: 0,
  },
  widthAuto: {
    paddingLeft: 24,
    paddingRight: 24,
    width: 'auto',
  },
})
