import {useCallback} from 'react'
import {SafeAreaView, View} from 'react-native'
import {msg, Trans} from '@lingui/macro'
import {useLingui} from '@lingui/react'
import {useQueryClient} from '@tanstack/react-query'

import {usePalette} from '#/lib/hooks/usePalette'
import {useUser} from '#/lib/hooks/useUser'
import {s} from '#/lib/styles'
import {isAndroid} from '#/platform/detection'
import {useModalControls} from '#/state/modals'
import {useSession} from '#/state/session'
import * as Toast from '#/view/com/util/Toast'
import {atoms as a} from '#/alf'
import {Button, ButtonIcon, ButtonText} from '#/components/Button'
import {TimesLarge_Stroke2_Corner0_Rounded as X} from '#/components/icons/Times'
import {Text} from '../util/text/Text'
import {ScrollView} from './util'

export const snapPoints = isAndroid ? ['90%'] : ['55%']

export function Component() {
  const pal = usePalette('default')

  const {_} = useLingui()
  const {currentAccount} = useSession()
  const {getUser} = useUser()
  const {closeModal} = useModalControls()
  const queryClient = useQueryClient()

  const onDone = useCallback(async () => {
    if (currentAccount?.did) {
      const data = await getUser(currentAccount?.did)
      const role = data?.role
      if (role === 'Gold' || role === 'SysAdmin') {
        queryClient.invalidateQueries({queryKey: ['subscriptionInfo']})
        closeModal()
      } else {
        Toast.show(
          'You have not completed your Stripe payment. Please try again!',
        )
      }
    }
  }, [currentAccount?.did, getUser, queryClient, closeModal])

  return (
    <SafeAreaView style={[s.flex1, {width: '100%', maxWidth: 432}]}>
      <ScrollView style={[pal.view]} keyboardShouldPersistTaps="handled">
        <View
          style={[
            pal.view,
            a.flex,
            a.flex_row,
            a.align_center,
            a.justify_between,
            a.mb_xl,
          ]}>
          <Text type="title-lg" style={[pal.text]}>
            <Trans>Stripe Payment</Trans>
          </Text>
          <Button
            label={_(msg`Hide verification complete`)}
            size="small"
            variant="ghost"
            color="secondary"
            shape="round"
            onPress={() => closeModal()}>
            <ButtonIcon icon={X} />
          </Button>
        </View>
        <View style={[a.flex, a.gap_sm, a.mb_2xl]}>
          <Text style={[pal.text, a.text_sm, a.font_normal, {opacity: 0.7}]}>
            Please complete your Stripe payment to continue.
          </Text>
        </View>

        <View style={[a.flex, a.flex_row, a.justify_end, a.gap_sm]}>
          <Button
            label={_(msg`Cancel`)}
            onPress={closeModal}
            size="small"
            variant="solid"
            color="secondary"
            style={[a.mt_sm, {width: 120}]}>
            <ButtonText>
              <Trans context="action">Cancel</Trans>
            </ButtonText>
          </Button>

          <Button
            label={_(msg`Explore`)}
            onPress={onDone}
            size="small"
            variant="solid"
            color="primary"
            style={[a.mt_sm, {width: 120}]}>
            <ButtonText>
              <Trans context="action">I'm done</Trans>
            </ButtonText>
          </Button>
        </View>
      </ScrollView>
    </SafeAreaView>
  )
}
