import {useState} from 'react'
import {ActivityIndicator, View} from 'react-native'
import {repSocialEmbedded, repSocialExtension} from '@fluxion-labs/rep-social'
import {msg, Trans} from '@lingui/macro'
import {useLingui} from '@lingui/react'

import {createCheckoutSession, PaymentType} from '#/lib/api/gold-member'
import {usePalette} from '#/lib/hooks/usePalette'
import {useModalControls} from '#/state/modals'
import {useProfileQuery} from '#/state/queries/profile'
import {useSession} from '#/state/session'
import * as Toast from '#/view/com/util/Toast'
import {atoms as a, useTheme, type ViewStyleProp} from '#/alf'
import {Button, ButtonText} from '#/components/Button'
import {Divider} from '#/components/Divider'
import {GoldBadgeIcon} from '#/components/icons/Badge'
import {CheckThick_Fill2_Corner0_Rounded as CheckIcon} from '#/components/icons/Check'
import * as Layout from '#/components/Layout'
import {Text} from '#/components/Typography'
import {UserAvatar} from '../util/UserAvatar'

export const getSuccessRedirectUrl = () => {
  if (typeof window === 'undefined') return '/'

  if (repSocialExtension.isChromeExtension) {
    const extensionOrigin =
      process.env.EXT_ORIGIN ?? 'https://prod-extension.rsky.ai'
    return `${extensionOrigin}?subscriptionStatus=success`
  }

  return `${window.location.origin}?subscriptionStatus=success`
}

export function WelcomeGoldMember() {
  const pal = usePalette('default')
  const t = useTheme()
  const {_} = useLingui()
  const {currentAccount} = useSession()
  const {data: currentProfile} = useProfileQuery({did: currentAccount?.did})
  const [isLoading, setIsLoading] = useState(false)
  const {openModal} = useModalControls()

  const onSubscribe = async () => {
    try {
      setIsLoading(true)
      const {data} = await createCheckoutSession({
        paymentType: PaymentType.SubcribeGoldMembership,
        userId: currentAccount?.did,
        successRedirectUrl: getSuccessRedirectUrl(),
        isRepSky: true,
      })
      setIsLoading(false)

      if (repSocialExtension.isChromeExtension) {
        repSocialExtension.redirectActiveTab({url: data.url})
        return
      }
      if (repSocialEmbedded.isEmbeddedInIframe) {
        window.open(data.url, '_blank')
        openModal({name: 'stripe-payment-confirmation'})
        return
      }
      window.location.href = data.url
    } catch (e) {
      Toast.show('Failed. Try again!')
      console.error(e)
    }
  }

  return (
    <Layout.Center style={[a.p_lg]}>
      <View style={[a.flex, a.align_center, a.gap_md, a.mt_2xl]}>
        <View style={[a.gap_sm, a.relative]}>
          <UserAvatar
            avatar={currentProfile?.avatar}
            size={50}
            style={[
              a.border,
              a.rounded_full,
              {
                borderColor: '#ECC78F',
                borderWidth: 2,
                borderRadius: '100%',
                boxSizing: 'content-box',
              },
            ]}
            type={'user'}
          />
          <GoldBadgeIcon
            style={{
              position: 'absolute',
              bottom: 1,
              left: 28,
              width: 24,
              height: 24,
            }}
          />
        </View>
        <Text style={[pal.text, a.font_bold, a.text_4xl, a.text_center]}>
          <Trans>Subscribe to Gold Member!</Trans>
        </Text>
        <View style={[a.flex, a.flex_row, a.align_baseline]}>
          <Text style={[pal.text, a.text_xl]}>
            <Trans>$10</Trans>
          </Text>
          <Text style={[pal.text, a.text_sm]}>
            <Trans>/month</Trans>
          </Text>
        </View>
      </View>
      <View
        style={[
          a.w_full,
          a.rounded_md,
          a.overflow_hidden,
          t.atoms.bg_contrast_25,
          a.mt_4xl,
        ]}>
        <View>
          <SubItem title={_(msg`Unlimited daily posts`)} />
        </View>
        <Divider />
        <View>
          <SubItem title={_(msg`Gold checkmark on your profile`)} />
        </View>
        <Divider />
        <View>
          <SubItem title={_(msg`Priority in feeds and discovery`)} />
        </View>
        <Divider />
        <View>
          <SubItem
            title={_(msg`Access to members-only features (coming soon)`)}
          />
        </View>
        <Divider />
        <View>
          <SubItem title={_(msg`Support via Stripe`)} />
        </View>
      </View>
      <View style={[a.flex, a.flex_row, a.justify_end, a.gap_sm, a.mt_sm]}>
        <Button
          label={_(msg`Subscribe`)}
          onPress={onSubscribe}
          size="large"
          variant="solid"
          color="primary"
          disabled={isLoading}
          style={[a.mt_sm, {width: 120}]}>
          {isLoading ? (
            <ActivityIndicator color="#d3d3d3" />
          ) : (
            <ButtonText>
              <Trans context="action">Subscribe</Trans>
            </ButtonText>
          )}
        </Button>
      </View>
    </Layout.Center>
  )
}

function SubItem({
  title,
  style,
}: ViewStyleProp & {
  title: string
}) {
  const t = useTheme()
  return (
    <View
      style={[
        a.w_full,
        a.flex_row,
        a.align_center,
        a.justify_between,
        a.p_lg,
        a.gap_sm,
        style,
      ]}>
      <View
        style={[
          a.flex_row,
          a.align_center,
          a.gap_md,
          {maxWidth: 'calc(100% - 40px)' as any},
        ]}>
        <Text style={[a.text_sm, t.atoms.text_contrast_high]}>{title}</Text>
      </View>
      <CheckIcon
        size="lg"
        style={[
          t.atoms.text_contrast_high,
          a.self_end,
          a.flex_shrink_0,
          {paddingTop: 2},
        ]}
      />
    </View>
  )
}
