import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
} from 'react'
import type React from 'react'

import {getUserInfo, type UserInfo} from '#/lib/api/user'
import * as Toast from '#/view/com/util/Toast'
import {useSession} from '../session'

type Ctx = {
  user: UserInfo | null
  isLoading: boolean
  getUser: (userId: string) => Promise<UserInfo | null | undefined>
  setUser: React.Dispatch<React.SetStateAction<UserInfo | null>>
}

const UserContext = createContext<Ctx | null>(null)

export function UserProvider({
  userId,
  children,
}: {
  userId: string | undefined
  children: React.ReactNode
}) {
  const {currentAccount} = useSession()
  const [user, setUser] = useState<UserInfo | null>(
    currentAccount?.did
      ? {
          handle: currentAccount?.did,
          role: 'Non',
        }
      : null,
  )
  const [isLoading, setIsLoading] = useState<boolean>(true)

  const getUser = useCallback(async (userId: string) => {
    try {
      setIsLoading(true)
      const data = await getUserInfo(userId)
      setUser(data)
      return data
    } catch (error) {
      console.error('Failed to fetch user kyc info:', error)
      Toast.show('Failed to fetch user kyc info. Please try again later.')
      setUser(null)
    } finally {
      setIsLoading(false)
    }
  }, [])

  // Initial load
  useEffect(() => {
    if (userId) {
      getUser(userId)
    }
  }, [getUser, userId])

  const value: Ctx = {user, isLoading, getUser, setUser}

  return <UserContext.Provider value={value}>{children}</UserContext.Provider>
}

export function useUserContext() {
  const ctx = useContext(UserContext)
  if (!ctx) throw new Error('useUserContext must be used within <UserProvider>')
  return ctx
}
