import {SafeAreaView, StyleSheet, TouchableOpacity, View} from 'react-native'
import {LinearGradient} from 'expo-linear-gradient'
import {msg, Trans} from '@lingui/macro'
import {useLingui} from '@lingui/react'

import {usePalette} from '#/lib/hooks/usePalette'
import {gradients, s} from '#/lib/styles'
import {isAndroid} from '#/platform/detection'
import {useVideoCall, type VideoModalData} from '#/state/call/context'
import {useModalControls} from '#/state/modals'
import {atoms as a} from '#/alf'
import {Text} from '../util/text/Text'
import {UserAvatar} from '../util/UserAvatar'
import {ScrollView} from './util'

export const snapPoints = isAndroid ? ['90%'] : ['55%']

export function Component({data}: {data: VideoModalData}) {
  const pal = usePalette('default')

  const {_} = useLingui()
  const {closeModal} = useModalControls()
  const {joinRoom, rejectCall} = useVideoCall()

  const onAccept = () => {
    joinRoom(data.roomId)
    closeModal()
  }

  const onReject = () => {
    rejectCall(data.roomId)
    closeModal()
  }

  const {isVideoCall, caller} = data
  const title = isVideoCall ? 'Incoming Video Call' : 'Incoming Call'
  const description = `${caller.displayName} is calling you ${
    isVideoCall ? 'for a video chat' : ''
  }`

  return (
    <SafeAreaView style={[s.flex1]}>
      <ScrollView style={[pal.view]} keyboardShouldPersistTaps="handled">
        <View style={[styles.titleContainer, pal.view]}>
          <Text type="title-lg" style={[s.textCenter, pal.text]}>
            <Trans>{title}</Trans>
          </Text>
        </View>
        <View
          style={[a.flex, a.flex_row, a.justify_center, a.gap_sm, a.mb_2xl]}>
          <UserAvatar avatar={caller?.avatar} size={50} type={'user'} />
        </View>
        <Text type="lg" style={[styles.description, pal.text]}>
          <Trans>{description}</Trans>
        </Text>

        <View style={[a.flex, a.flex_row, a.justify_center, a.gap_sm]}>
          <TouchableOpacity
            style={[styles.btn, s.mt10]}
            onPress={onReject}
            accessibilityRole="button"
            accessibilityLabel={_(msg`Reject call`)}
            accessibilityHint=""
            onAccessibilityEscape={onReject}>
            <Text type="button-lg" style={pal.textLight}>
              <Trans context="action">Reject</Trans>
            </Text>
          </TouchableOpacity>
          <TouchableOpacity
            style={styles.mt20}
            onPress={onAccept}
            accessibilityRole="button"
            accessibilityLabel={_(msg`Send email`)}
            accessibilityHint={_(msg`Accept call`)}>
            <LinearGradient
              colors={[gradients.blueLight.start, gradients.blueLight.end]}
              start={{x: 0, y: 0}}
              end={{x: 1, y: 1}}
              style={[styles.btn]}>
              <Text type="button-lg" style={[s.white, s.bold]}>
                <Trans context="action">Accept</Trans>
              </Text>
            </LinearGradient>
          </TouchableOpacity>
        </View>
      </ScrollView>
    </SafeAreaView>
  )
}

const styles = StyleSheet.create({
  titleContainer: {
    display: 'flex',
    flexDirection: 'row',
    justifyContent: 'center',
    flexWrap: 'wrap',
    marginTop: 12,
    marginBottom: 12,
    marginLeft: 20,
    marginRight: 20,
  },
  description: {
    textAlign: 'center',
    paddingHorizontal: 22,
    marginBottom: 10,
  },
  mt20: {
    marginTop: 20,
  },
  btn: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: 32,
    padding: 14,
    marginHorizontal: 20,
  },
})
