import {useCallback, useState} from 'react'
import {initCycurid} from 'cycurid-sdk'

import {verifyCycuridOnBackend} from '#/lib/api/user'
import {useModalControls} from '#/state/modals'
import {useUserContext} from '#/state/user/context'
import * as Toast from '#/view/com/util/Toast'
import {communityPrefix, MERCHAINT_KEY_BY_ENV} from '../rep-social-env'

type VerifyMode = 'onboarding' | 'isHuman'

export function useUser() {
  const {user, isLoading, getUser, setUser} = useUserContext()
  const [verifying, setVerifying] = useState(false)
  const {openModal} = useModalControls()

  const verifyUser = useCallback(
    async (userId: string, mode: VerifyMode = 'onboarding') => {
      if (!userId) {
        Toast.show('Missing user id')
        return {ok: false}
      }

      setVerifying(true)
      try {
        // Step 1: Initialize Cycurid verification on frontend
        const initResult = await initCycurid(
          MERCHAINT_KEY_BY_ENV[communityPrefix],
          userId,
          mode, // 'onboarding' or 'isHuman'
        )

        // Step 2: Notify backend to verify the result
        const userInfo = await verifyCycuridOnBackend({
          handle: userId,
          sessionId: initResult.sessionId,
        })

        if (userInfo) {
          setUser(userInfo)
          openModal({
            name: 'verification-complete',
            data: {handle: userId, role: 'Silver'},
          })
          return {ok: true}
        } else {
          Toast.show('Verification failed')
          return {ok: false}
        }
      } catch (err: unknown) {
        const message =
          err instanceof Error ? err.message : 'Verification failed'
        Toast.show(message)
        return {ok: false, error: message}
      } finally {
        setVerifying(false)
      }
    },
    [setUser, openModal],
  )

  return {
    user,
    isLoading,
    verifying,
    getUser,
    setUser,
    verifyUser,
  }
}
