import {useCallback, useEffect} from 'react'
import {ActivityIndicator} from 'react-native'
import {Trans} from '@lingui/macro'
import {useLingui} from '@lingui/react'
import {useNavigation} from '@react-navigation/native'
import {useQuery, useQueryClient} from '@tanstack/react-query'

import {
  getSubscriptionInfo,
  type PaymentInfoItem,
  PaymentMethod,
} from '#/lib/api/gold-member'
import {useUser} from '#/lib/hooks/useUser'
import {
  type CommonNavigatorParams,
  type NativeStackScreenProps,
} from '#/lib/routes/types'
import {type NavigationProp} from '#/lib/routes/types'
import {useModalControls} from '#/state/modals'
import {useSession} from '#/state/session'
import * as Toast from '#/view/com/util/Toast'
import {atoms as a} from '#/alf'
import * as Layout from '#/components/Layout'
import {PaymentHistory} from '../com/subscription/PaymentHistory'
import {WelcomeGoldMember} from '../com/subscription/WelcomeGoldMember'

type Props = NativeStackScreenProps<CommonNavigatorParams, 'Subscription'>
export function SubscriptionScreen({}: Props) {
  const {_} = useLingui()
  const {currentAccount} = useSession()
  const did = currentAccount?.did
  const navigation = useNavigation<NavigationProp>()
  const {openModal} = useModalControls()
  const routes = navigation.getState().routes
  const currentRoute = routes[routes.length - 1]
  const params = currentRoute.params
  const status =
    params && 'status' in params ? (params as any).status : undefined

  const {user} = useUser()
  const queryClient = useQueryClient()

  const {
    data: subscriptions = [],
    isLoading,
    error,
  } = useQuery({
    queryKey: ['subscriptionInfo', PaymentMethod.Stripe, did],
    queryFn: () =>
      getSubscriptionInfo(PaymentMethod.Stripe, did).then(res => res.data),
    enabled: !!did,
  })

  if (error) {
    Toast.show('Failed to load subscription info')
  }

  const activeSubscription =
    subscriptions.find(item => item.status === 'active') || null

  const setCancelCurrentActiveSubscription = useCallback(() => {
    queryClient.setQueryData(
      ['subscriptionInfo', PaymentMethod.Stripe, did],
      (subs?: PaymentInfoItem[]) =>
        subs
          ? subs.map(sub => {
              if (sub.status === 'active') {
                sub.status = 'canceled'
              }
              return {...sub}
            })
          : [],
    )
  }, [queryClient, did])

  useEffect(() => {
    if (activeSubscription && status === 'success') {
      openModal({
        name: 'stripe-payment-success',
        data: activeSubscription,
      })
    }
  }, [status, activeSubscription, openModal])

  return (
    <Layout.Screen testID="subscriptionScreen">
      <Layout.Header.Outer>
        <Layout.Header.BackButton />
        <Layout.Header.Content align="left">
          <Layout.Header.TitleText>
            <Trans>Subscription</Trans>
          </Layout.Header.TitleText>
        </Layout.Header.Content>
      </Layout.Header.Outer>
      {isLoading ? (
        <ActivityIndicator size="large" style={[a.m_2xl]} color="#d3d3d3" />
      ) : (
        <>
          {user?.role !== 'SysAdmin' && user?.role !== 'Gold' && (
            <WelcomeGoldMember />
          )}

          {subscriptions.length > 0 && (
            <PaymentHistory
              subscription={
                activeSubscription ?? subscriptions[subscriptions.length - 1]
              }
              onRefresh={setCancelCurrentActiveSubscription}
            />
          )}
        </>
      )}
    </Layout.Screen>
  )
}
