// src/lib/hooks/usePostQuota.ts
import {useCallback, useMemo} from 'react'
import {useQuery, useQueryClient} from '@tanstack/react-query'
import {differenceInCalendarDays} from 'date-fns'

import {useProfileShadow} from '#/state/cache/profile-shadow'
import {useProfileQuery} from '#/state/queries/profile'
import {useAgent, useSession} from '#/state/session'
import {useFullVerificationState} from '#/components/verification'
import {shouldShowVerificationCheckButton} from '#/components/verification/VerificationCheckButton'
import {isPremiumRole, isSilverRole, isStandardRole} from '../api/user'
import {communityPrefix} from '../rep-social-env'
import {getRskyInfo} from '../rsky-profile'
import {useUser} from './useUser'

const SILVER_POST_LIMIT = 10
export const MIN_FOLLOWERS_FALLBACK = 100
export type QuotaWindow = 'hour' | 'day'

interface UsePostQuotaOpts {
  quotaWindow?: QuotaWindow // 'hour' (test) -or- 'day' (default)
}

declare global {
  interface Window {
    minFollowersCount: number | null
  }
}

window.addEventListener('message', event => {
  const {action, data} = event.data || {}

  switch (action) {
    case 'urlChange':
      break

    case 'minFollowersCount':
      window.minFollowersCount = data
      break

    default:
      console.warn('Unknown message action:', action)
  }
})

export function usePostQuota({quotaWindow = 'day'}: UsePostQuotaOpts = {}) {
  const {currentAccount} = useSession()
  const did = currentAccount?.did
  const agent = useAgent()
  const qc = useQueryClient()
  const {user} = useUser()

  const {data: repSkyInfo, isFetching: loadingRskyInfo} = useQuery({
    queryKey: ['repSkyInfo'],
    queryFn: getRskyInfo,
    staleTime: 5 * 60 * 1_000, // cache 5 min
    retry: 2,
  })

  const whiteDidList = repSkyInfo?.whiteDidlist ?? []

  /* ───────── not logged in ───────── */
  if (!did) {
    return {
      loading: false,
      canPost: false,
      remaining: 0,
      windowKind: quotaWindow,
      refresh: () => {},
      postLimit: SILVER_POST_LIMIT,
      windowPosts: [],
    } as const
  }

  const {data: profile, isFetching: loadingProfile} = useProfileQuery({
    did,
    staleTime: 0,
  })

  const shadow = useProfileShadow(profile as any)
  const verificationState = useFullVerificationState({profile: shadow})

  const WINDOW_MS = quotaWindow === 'hour' ? 3_600_000 : 86_400_000
  const {data: windowPosts, isFetching: loadingFeed} = useQuery({
    queryKey: ['feedWindow', did, quotaWindow],
    queryFn: async () => {
      const res = await agent.api.app.bsky.feed.getAuthorFeed({
        actor: did,
        limit: 100,
      })
      const now = Date.now()
      return res.data.feed
        .filter(item =>
          String(item.post.record.community).startsWith(`${communityPrefix}:`),
        )
        .filter((item: any) => {
          const created = new Date(item.post.record.createdAt).getTime()
          if (quotaWindow === 'hour') return now - created < WINDOW_MS
          return (
            now - created < WINDOW_MS &&
            differenceInCalendarDays(created, now) === 0
          )
        })
    },
    staleTime: 0,
    refetchOnMount: 'always',
  })

  /* ───────── eligibility ───────── */
  const qualified =
    !isStandardRole(user?.role) ||
    shouldShowVerificationCheckButton(verificationState) ||
    whiteDidList.includes(did)

  const postLimit = useMemo(() => {
    if (isPremiumRole(user?.role)) {
      return Number.POSITIVE_INFINITY
    }
    if (isSilverRole(user?.role)) {
      return SILVER_POST_LIMIT
    }
    return 0
  }, [user?.role])
  const remaining = useMemo(() => {
    if (isSilverRole(user?.role)) {
      return postLimit - (windowPosts?.length ?? 0)
    }
    return postLimit
  }, [postLimit, user?.role, windowPosts?.length])
  const canPost = qualified && remaining > 0

  /* ───────── refresh helper ───────── */
  const refresh = useCallback(() => {
    qc.invalidateQueries({queryKey: ['feedWindow', did, quotaWindow]})
    qc.invalidateQueries({queryKey: ['profile', did]})
    qc.invalidateQueries({queryKey: ['minFollowers']})
  }, [qc, did, quotaWindow])

  /* ───────── exposed API ───────── */
  return {
    loading: loadingProfile || loadingFeed || loadingRskyInfo,
    canPost,
    remaining: Math.max(0, remaining),
    refresh,
    postLimit,
    qualified,
  }
}
