import {useEffect} from 'react'
import {
  EmbededAction,
  type EmbededEventMap,
  ExtensionAction,
  type ExtensionEventMap,
  repSocialEmbedded,
  repSocialExtension,
} from '@fluxion-labs/rep-social'
import {useQueryClient} from '@tanstack/react-query'

import {useSession} from '#/state/session'
import * as Toast from '#/view/com/util/Toast'
import {useUser} from './useUser'

export const useRepSocialSetup = () => {
  const {currentAccount} = useSession()
  const {getUser} = useUser()
  const queryClient = useQueryClient()

  useEffect(() => {
    if (!repSocialExtension.isChromeExtension) return

    const onSuccessGMSubscription: ExtensionEventMap['onSuccessGMSubscription'] =
      async () => {
        if (currentAccount?.did) {
          const data = await getUser(currentAccount?.did)
          const role = data?.role
          if (role === 'Gold' || role === 'SysAdmin') {
            queryClient.invalidateQueries({queryKey: ['subscriptionInfo']})
          } else {
            Toast.show(
              'You have not completed your Stripe payment. Please try again!',
            )
          }
        } else {
          Toast.show('Handle is not found')
        }
      }

    repSocialExtension.on('onSuccessGMSubscription', onSuccessGMSubscription)

    return () => {
      repSocialExtension.off('onSuccessGMSubscription', onSuccessGMSubscription)
    }
  }, [getUser, currentAccount?.did, queryClient])

  useEffect(() => {
    if (!repSocialEmbedded.isEmbedded) return

    const onSuccessGMSubscription: EmbededEventMap['onSuccessGMSubscription'] =
      () => {
        // ModalUtils.actionGoldMember.onClose();
        window.location.reload()
      }

    repSocialEmbedded.on('onSuccessGMSubscription', onSuccessGMSubscription)
    return () => {
      repSocialEmbedded.off('onSuccessGMSubscription', onSuccessGMSubscription)
    }
  }, [])

  useEffect(() => {
    if (
      !repSocialEmbedded.isEmbedded &&
      !repSocialExtension.isChromeExtension &&
      typeof window !== 'undefined'
    ) {
      const params = new URLSearchParams(location.search)
      const subscriptionStatus = params.get('subscriptionStatus')
      if (subscriptionStatus === 'success') {
        repSocialExtension.communicateToExtension(
          ExtensionAction.SuccessGMSubscription,
        )

        repSocialEmbedded.communicateToEmbedded(
          EmbededAction.SuccessGMSubscription,
        )
      }
    }
  }, [])
}
